[4725] = { en = "Beached Sea Turtle", tier = 1,
  t = "Aangespoelde zeeschildpad",
  d = "Langs de kust liggen nog meer resten van zeeschildpadden. Aan het schild van deze schildpad zit een verlaten wagen vast. Misschien is dit dier door onbekende wezens naar de kust gedreven. Dan is het niet zelf aangespoeld, zoals sommige andere resten deden denken. Greymist murlocs wonen nu in de resten van dit dier en smullen van het dode vlees.$B$BIn de wagen vind je een doos met vreemde tekens erop. Misschien begrijpt Gwennyth Bly'Leggonde in Auberdine wat ze betekenen.",
  o = "Breng de Strangely Marked Box naar Gwennyth Bly'Leggonde in Auberdine.",
  p = "Wat fijn om je weer te zien, $N. We komen steeds verder met het mysterie waarom prachtige zeedieren op de kust van Darkshore aanspoelen. Maar het lijkt erop dat er bij elke vraag die we beantwoorden, twee nieuwe vragen bij komen.$b$bKom je ons nog meer helpen met ons onderzoek?",
  c = "Ik heb gehoord over het soort wagen dat jij op de rug van de schildpad vond. Ik denk echt dat het wagens van de naga zijn. Ze gebruiken ze in gevechten, en ook om hun voorraden aan land te brengen. De tekens op de doos zijn van de naga. Dat zou verklaren waarom ze het verre noorden van Darkshore binnendringen.$b$bIk stuur deze doos naar Darnassus, samen met de rest van je ontdekkingen. Dit is voor jou. Nogmaals bedankt voor je hulp.",
  g = { {"resten", "remains (rest)"}, {"schild", "shell"}, {"verlaten", "abandoned"}, {"gedreven", "driven (drijven)"}, {"aangespoeld", "washed up, beached (aanspoelen)"}, {"smullen", "feast"}, {"tekens", "markings, signs (teken)"}, {"mysterie", "mystery"}, {"beantwoorden", "answer"}, {"verklaren", "explain"}, {"binnendringen", "invade, push into"}, {"ontdekkingen", "discoveries (ontdekking)"} },
},

[4727] = { en = "Beached Sea Turtle", tier = 1,
  t = "Aangespoelde zeeschildpad",
  d = "Het skelet van een zeeschildpad ligt in het zand van de stranden in het noorden van Darkshore. Misschien hebben de Greymist murlocs dit karkas nog niet gevonden. Of misschien hebben ze het wel gevonden en blijven ze er om een onbekende reden bij weg. Hoe dan ook, er is nog genoeg van de schildpad over om een monster mee te nemen naar Gwennyth Bly'Leggonde in Auberdine. Dan kan de Temple of the Moon het bestuderen.",
  o = "Breng de Sea Turtle Remains naar Gwennyth Bly'Leggonde in Auberdine.",
  p = "Hallo weer, $N! Kom je vertellen over nog een ontdekking?",
  c = "De botten die je hebt, zijn van rustige zeezoogdieren. Het is bekend dat ze leven in het water rond de voet van Teldrassil. Van deze dieren was nooit bekend dat ze zich met geweld op het strand gooien, zoals de voshaaien dat wel deden. Waarom zouden deze dieren dat doen, vraag ik me af? Nou, misschien levert het onderzoek naar hun resten de vruchten van kennis op die we zoeken.$B$BNogmaals bedankt voor je hulp. Neem alsjeblieft deze vergoeding aan van de Temple of the Moon.",
  g = { {"skelet", "skeleton"}, {"karkas", "carcass"}, {"blijven weg", "stay away (wegblijven)"}, {"hoe dan ook", "regardless, anyway"}, {"monster", "sample"}, {"zeezoogdieren", "sea mammals (zeezoogdier)"}, {"met geweld", "violently"}, {"voshaaien", "threshers, thresher sharks (voshaai)"}, {"levert op", "yields, brings (opleveren)"}, {"vruchten", "fruits (vrucht)"}, {"kennis", "knowledge"}, {"nogmaals", "again, once more"}, {"vergoeding", "honorarium, payment"} },
},

[4761] = { en = "Thundris Windweaver", tier = 1,
  t = "Thundris Windweaver",
  d = "Thundris Windweaver moet weten wat je bij het furbolgkamp hebt ontdekt. Hij is zo vriendelijk om de dorpsoudste van Auberdine te zijn. Hij leidt de dagelijkse zaken van het dorp met wijsheid en rechtvaardigheid. Vertel hem alsjeblieft wat je tot nu toe over de furbolgs weet.$B$BIk denk dat hij zelf ook ideeën heeft over de reden waarom ze verdorven zijn. Misschien kun je met hem samenwerken aan een plan om het evenwicht van de natuur hier te herstellen!",
  o = "Praat met Thundris Windweaver in Auberdine.",
  c = "Gegroet, $c. Je onderzoek naar de furbolgs komt voor ons in Auberdine op een gelukkig moment. Al een tijd hebben we niet alleen te maken met bosbewoners die nu openlijk vijandig tegen ons zijn, maar ook met de verdorvenheid van het bos zelf. Hopelijk kun je Auberdine helpen in deze moeilijke tijden.",
  g = { {"dorpsoudste", "village elder"}, {"dagelijkse", "daily, day-to-day (dagelijks)"}, {"zaken", "affairs (zaak)"}, {"wijsheid", "wisdom"}, {"rechtvaardigheid", "justice, fairness"}, {"verdorven", "corrupted"}, {"evenwicht", "balance"}, {"herstellen", "restore"}, {"bosbewoners", "forest dwellers (bosbewoner)"}, {"openlijk", "openly"}, {"vijandig", "hostile"}, {"verdorvenheid", "corruption"} },
},

[4762] = { en = "The Cliffspring River", tier = 1,
  t = "De Cliffspring River",
  d = "De Cliffspring River begint vies en verdorven te worden. De rivier stroomt uit in de Mist's Edge, en ik ben bang dat het vuile water Auberdine snel zal bereiken. Ik denk dat de Blackwood-furbolgs stroomopwaarts de oorzaak van de vervuiling zijn. Maar ik denk ook dat ze niet de echte bron ervan zijn.$B$BNeem dit buisje voor monsters mee en ga naar de monding van de rivier, ten noorden van ons. Ga het land in tot de eerste waterval en neem daar een monster uit de poel. Je ziet een brug boven je. Als je een monster hebt, kom dan terug naar mij in Auberdine.",
  o = "Reis naar het noorden van Auberdine, naar de eerste waterval langs de Cliffspring River, en neem daar een monster uit de poel.$B$BGa met de Cliffspring River Sample terug naar Thundris Windweaver in Auberdine.",
  p = "De vervuiling van de Cliffspring River is nog maar het begin van een zorgwekkende ontwikkeling hier in Darkshore. Het monster dat je brengt, helpt ons om een plan te maken... een aanvalsplan, begin ik te denken.",
  c = "Het is geen verrassing dat dit water vervuild is. Maar kijk eens hoe rot het wordt! Het lijkt erop dat we eerder moeten ingrijpen dan later, hè $N?$b$bTen oosten van ons ligt Felwood. Dat is de echte bron van deze verdorvenheid. Ik heb die vroeger al eens gezien. Ik voorspel dat dit monster dat zal bevestigen. Misschien kunnen we hier een geneesmiddel maken. Maar om het zelfs maar te proberen, hebben we hulp nodig. Als het zover is, $N, hoop ik dat jij ons de hulp kunt geven die we nodig hebben.",
  g = { {"stroomt uit", "empties into (uitstromen)"}, {"stroomopwaarts", "up-river"}, {"oorzaak", "cause"}, {"vervuiling", "pollution, taint"}, {"buisje", "small tube (buis)"}, {"monding", "mouth (of a river)"}, {"poel", "pool"}, {"ontwikkeling", "development, trend"}, {"vervuild", "polluted, tainted"}, {"ingrijpen", "take action, intervene"}, {"voorspel", "predict (voorspellen)"}, {"bevestigen", "confirm"}, {"geneesmiddel", "cure, medicine"}, {"als het zover is", "when that time comes"} },
},

[5713] = { en = "One Shot.  One Kill.", tier = 1,
  t = "Eén schot. Eén dode.",
  d = "Ik was op weg naar Auberdine met een belangrijk bericht. Toen werd ik aangevallen door de furbolg Marosh en zijn spoorzoekers. Tijdens de aanval werd ik vergiftigd. Nu kan ik bijna niet meer staan. Ik kan een tegengif maken, maar het duurt even voordat het klaar is.$B$BWil je me beschermen tot ik het tegengif kan gebruiken? Ik help je met mijn boog, zo goed als ik kan.$B$BAls we het overleven, kan ik mijn bericht naar Auberdine brengen. Dan praat jij met Onaeya in Maestra's Post en vertel je haar wat er is gebeurd.",
  o = "Bescherm Sentinel Aynasha en praat daarna met Onaeya in Maestra's Post in Ashenvale.",
  p = "Heb je Sentinel Aynasha op de weg gezien? Ze is vertrokken voor een belangrijke opdracht, maar ze is nog niet terug.",
  c = "Je brengt heel welkom nieuws, $C. Het is fijn om te horen dat Aynasha dankzij jou nog leeft en gezond is. Ik hoop dat je een beloning wilt aannemen voor je moed. Moge Elune over je waken en je pad verlichten.",
  e = "Bescherm Aynasha",
  g = { {"schot", "shot"}, {"spoorzoekers", "trackers (spoorzoeker)"}, {"vergiftigd", "poisoned (vergiftigen)"}, {"tegengif", "antidote"}, {"overleven", "survive"}, {"dankzij", "thanks to"}, {"aannemen", "accept"}, {"moed", "valor, courage"}, {"moge", "may (mogen)"}, {"waken", "watch over"}, {"verlichten", "light (up)"} },
},

[963] = { en = "For Love Eternal", tier = 1,
  t = "Voor eeuwige liefde",
  d = "Na de gevechten bij de Well of Eternity hoorde ik dat Ameth'Aran vernietigd was. De bewoners waren dood, ook mijn geliefde, Anaya.$b$bIk had nooit gedacht dat herinneringen aan Anaya duizenden jaren later nog steeds door mijn dromen zouden spoken. Half verdoofd dwaalde ik door de bossen van Darkshore, en ik kwam terecht in de ruïnes van Ameth'Aran... Daar zag ik de gekwelde geest van mijn geliefde.$b$bZe moet bevrijd worden, maar ik heb er het hart niet voor. Haar geest moet vernietigd worden.",
  o = "Bevrijd de geest van Anaya Dawnrunner en breng haar hanger terug naar Cerellean Whiteclaw in Auberdine.",
  p = "Met groot verdriet in mijn hart volgde ik de Shan'do Stormrage in zijn winterslaap. Ik nam mijn verdriet mee in mijn dromen, en ik sliep duizenden jaren lang.",
  c = "Dank je, $n. Misschien was het beter geweest... als ik het zelf had gedaan. Maar zelfs na al die duizenden jaren kon ik mijn hand niet opheffen tegen mijn geliefde.$b$bAlsjeblieft, ik wil alleen zijn met mijn rouw...",
  g = { {"eeuwige", "eternal (eeuwig)"}, {"bewoners", "inhabitants, people (bewoner)"}, {"geliefde", "beloved, love"}, {"herinneringen", "memories (herinnering)"}, {"spoken", "haunt"}, {"verdoofd", "dazed, in a stupor"}, {"dwaalde", "wandered (dwalen)"}, {"terecht", "ended up (terechtkomen)"}, {"gekwelde", "tormented, haunted (gekweld)"}, {"bevrijd", "freed (bevrijden)"}, {"hanger", "pendant"}, {"winterslaap", "hibernation"}, {"opheffen", "raise"}, {"rouw", "grief, mourning"} },
},

[1003] = { en = "Buzzbox 525", tier = 1,
  t = "Buzzbox 525",
  d = "Boven het borrelen en druppelen van de machine uit hoor je de trillende stem van Wizbang.$B$B\"De volgende... *hik*... staat ver naar het zuiden, langs de weg. Niet moeilijk te vinden... gewoon aan de kant... bij een hek. Ik geloof dat ik hem in wat struiken heb verstopt... Struiken. Struikjes! Hihihi... Ja, Buzzbox 525 neemt Grizzled Scalps van die Grizzled Thistle Bears. Tjonge, dat is een hele mondvol. Grizzled... Hihihi...\"$B$BJe hoort nog meer slokken, en dan valt de machine stil. Dan komt hij opeens weer tot leven.$B$B\"4!\"",
  o = "Verzamel 4 Grizzled Scalps van Grizzled Thistle Bears ten zuiden van Auberdine en stop ze in Buzzbox 525.",
  p = "Je hoort gezang uit Buzzbox 525.$b$b\"Al is crawlerwijn zoet, en thresherbier fijn, en moonstalker-stookdrank geweldig: niets is zo lief als thistle-bear-bier, en straks heb ik er wat van bij de hand!\"$b$bHet luik staat open en wacht op de 4 Grizzled Scalps. Je hoort het lied steeds opnieuw.",
  c = "\"Dus je hebt de scalps erin gedaan? Wat geweldig... Wat? Nou ja, je hebt vast door dat ik met je kan praten zonder dat de spullen in de machine zitten. Maar ik zei de waarheid toen ik zei dat ze kapot waren!$b$bKijk, de Buzzboxes zijn niet alleen communi... communica... communicatieapparaten. Ze brouwen en stoken ook fijne drank. Sorry dat ik niet eerlijk was, maar de nachtelfen waarde... *hik*... waarderen mijn drankhandel in hun dorpen niet. Ik heb iets speciaals in deze doos gestopt om je te bedanken voor al je moeite. Geniet ervan!\"",
  g = { {"borrelen", "bubbling, boiling"}, {"druppelen", "dripping"}, {"trillende", "wavering, shaking (trillen)"}, {"hek", "fence"}, {"struiken", "bushes (struik)"}, {"mondvol", "mouthful"}, {"slokken", "gulps (slok)"}, {"stookdrank", "moonshine, distilled liquor"}, {"luik", "hatch"}, {"je hebt door", "you have realized (doorhebben)"}, {"communicatieapparaten", "communication devices (apparaat)"}, {"brouwen", "brew"}, {"stoken", "distill"}, {"waarderen", "appreciate"}, {"drankhandel", "liquor trade"} },
},

[2138] = { en = "Cleansing of the Infected", tier = 1,
  t = "De zieken reinigen",
  d = "Zoals ik al vreesde, werkt het geneesmiddel niet.$B$BHet maakt me heel verdrietig om de dood te bevelen van dieren van de natuur. Maar de zieke en besmette Thistle Bears moeten worden afgemaakt.$B$BGa terug naar het bos en dood 20 hondsdolle Thistle Bears, $N. Het zal de plaag zeker niet stoppen. Maar het vertraagt wel een korte tijd de schade die deze dieren aan ons bos en zijn bewoners doen.",
  o = "Dood 20 Rabid Thistle Bears om het bos te reinigen en ga terug naar Tharnariun Treetender in Darkshore.",
  p = "Is je taak klaar?",
  c = "Je hebt Auberdine een grote dienst bewezen, $N, maar je taak is nog niet klaar.",
  g = { {"zieken", "the sick (ziek)"}, {"reinigen", "cleanse"}, {"vreesde", "feared (vrezen)"}, {"geneesmiddel", "cure"}, {"verdrietig", "sad"}, {"bevelen", "order, command"}, {"besmette", "infected, tainted (besmet)"}, {"afgemaakt", "put down (afmaken)"}, {"hondsdolle", "rabid (hondsdol)"}, {"plaag", "plague"}, {"vertraagt", "slows down (vertragen)"}, {"een dienst bewezen", "did a service (bewijzen)"} },
},

[4730] = { en = "Beached Sea Creature", tier = 1,
  t = "Gestrand zeedier",
  d = "Op het strand ligt het half opgegeten lijk van iets dat misschien een enorm zeezoogdier was. Een groep murlocs, sterker dan die dichter bij Auberdine, woont nu rond het dode dier. Er is nog genoeg van het dier over om een goed monster van zijn botten naar Gwennyth Bly'Leggonde in Auberdine te brengen.",
  o = "Breng de Sea Creature Bones naar Gwennyth Bly'Leggonde in Auberdine.",
  p = "Hallo weer, $N! Kom je vertellen over nog een ontdekking?",
  c = "De botten die je hebt, zijn van rustige zeezoogdieren. Het is bekend dat ze leven in het water rond de voet van Teldrassil. Van deze dieren was nooit bekend dat ze zich met geweld op het strand gooien, zoals de voshaaien dat wel deden. Waarom zouden deze dieren dat doen, vraag ik me af? Nou, misschien levert het onderzoek naar hun resten de vruchten van kennis op die we zoeken.$B$BNogmaals bedankt voor je hulp. Neem alsjeblieft deze vergoeding aan van de Temple of the Moon.",
  g = { {"gestrand", "beached"}, {"opgegeten", "eaten (opeten)"}, {"lijk", "corpse"}, {"enorm", "huge"}, {"monster", "sample"}, {"zeezoogdieren", "sea mammals (zeezoogdier)"}, {"met geweld", "violently"}, {"voshaaien", "threshers, thresher sharks (voshaai)"}, {"levert op", "yields, brings (opleveren)"}, {"vruchten", "fruits (vrucht)"}, {"kennis", "knowledge"}, {"nogmaals", "again, once more"}, {"vergoeding", "honorarium, payment"} },
},

[944] = { en = "The Master's Glaive", tier = 1,
  t = "De Master's Glaive",
  d = "Het is vreemd dat de naga hier in Darkshore zijn. Maar nog vreemder... is de Twilight's Hammer. Die sekte aanbidt de oude, oude heersers van de aarde. Heersers die lang geleden verslagen zijn.$B$BDe Master's Glaive, in het zuiden, is een plek waar zo'n oude heerser viel.$B$BGa daarheen en zoek naar meer cultisten van de Twilight's Hammer.$B$BNeem dit waarzegflesje mee. Gebruik het om een waarzegschaal te maken, nadat je de Master's Glaive hebt doorzocht. Praat dan met mij via de schaal.",
  o = "Verzamel informatie en gebruik dan de Phial of Scrying om een Scrying Bowl te maken. Gebruik de schaal om met Onu te praten.",
  p = "De Master's Glaive, $N.$B$BGa daarheen, en praat dan weer met mij.",
  c = "Is de Twilight's Hammer bij de Master's Glaive?$b$bDat is jammer.$b$bDe oude heerser die door de glaive werd doorboord, is al lang dood. Maar dat betekent niet dat er geen splinters van zijn macht meer over zijn.$b$bDe Twilight's Hammer zoekt vast deze macht.",
  e = "Ga naar de Master's Glaive",
  g = { {"sekte", "cult"}, {"aanbidt", "worships (aanbidden)"}, {"heersers", "lords, rulers (heerser)"}, {"verslagen", "defeated (verslaan)"}, {"cultisten", "cultists (cultist)"}, {"waarzegflesje", "phial of scrying"}, {"waarzegschaal", "scrying bowl"}, {"doorzocht", "searched (doorzoeken)"}, {"jammer", "unfortunate, a pity"}, {"doorboord", "impaled, pierced (doorboren)"}, {"splinters", "slivers (splinter)"}, {"macht", "power"} },
},

[947] = { en = "Cave Mushrooms", tier = 1,
  t = "Grotpaddenstoelen",
  d = "Ik maak een drankje waarvoor ik zeldzame paddenstoelen nodig heb. Ze groeien alleen in één bepaalde grot. De grot ligt achter de Cliffspring Falls, in het oosten en een beetje naar het noorden, langs de bergen.$B$BIk zou er zelf heen gaan, maar de Grove of the Ancients heeft me aangeraden om daar weg te blijven. Onze eerbiedwaardige bondgenoten voelen dat de grot de schuilplaats is van een nieuw kwaad in Darkshore.$B$BAlsjeblieft, $N, verzamel de paddenstoelen voor mij. En verken tegelijk de grot, om te bevestigen waar de Ancients bang voor zijn.",
  o = "Breng 5 Scaber Stalks en 1 Death Cap naar Barithras Moonshade in Auberdine.",
  p = "Heb je mijn paddenstoelen, $N? Ben je in de grot geweest?",
  c = "Heel erg bedankt, $N. Dit zijn mooie exemplaren!$b$bEn toen je bij de Cliffspring Falls was, heb je toen iets gevonden dat de waarschuwingen van de Ancients bevestigt?$b$bDe Ancients zijn wijs, maar ik had gehoopt dat ze het deze keer mis hadden.",
  g = { {"paddenstoelen", "mushrooms (paddenstoel)"}, {"zeldzame", "rare (zeldzaam)"}, {"bepaalde", "certain, particular (bepaald)"}, {"aangeraden", "advised (aanraden)"}, {"eerbiedwaardige", "venerable (eerbiedwaardig)"}, {"bondgenoten", "allies (bondgenoot)"}, {"schuilplaats", "hiding place"}, {"kwaad", "evil"}, {"verken", "scout (verkennen)"}, {"exemplaren", "specimens (exemplaar)"}, {"waarschuwingen", "warnings (waarschuwing)"}, {"het mis hebben", "be wrong"} },
},

[948] = { en = "Onu", tier = 1,
  t = "Onu",
  d = "Onu, een Ancient of Lore in de Grove of the Ancients, weet van je tocht naar de Cliffspring Falls en wil met je praten. Het bos ligt in het zuiden, dicht tegen de bergen aan.$B$BDe Ancients zijn geduldig en wijs, $N. Maar als Onu jouw raad zoekt over wat je bij de waterval hebt gezien, dan ben ik bang dat het dringend is.",
  o = "Praat met Onu in de Grove of the Ancients.",
  c = "$N. Je bent er.$b$bGoed.$b$bWe moeten... over dingen praten. Jij en ik.",
  g = { {"tocht", "journey, trip"}, {"dicht tegen", "nestled against"}, {"geduldig", "patient"}, {"wijs", "wise"}, {"raad", "counsel, advice"}, {"waterval", "waterfall"}, {"dringend", "urgent"} },
},

[949] = { en = "The Twilight Camp", tier = 1,
  t = "Het Twilight-kamp",
  d = "Niemand weet waarom de Twilight's Hammer bij de Master's Glaive is. Maar het moet iets duisters zijn.$B$BDoorzoek hun kamp bij de Glaive... Zoek iets dat ons hun bedoelingen kan leren.$B$BWant we moeten hun bedoelingen kennen, voordat we een plan maken.",
  o = "Zoek een aanwijzing in het kamp van de Twilight's Hammer bij de Master's Glaive.",
  c = "Dit boek is met de hand geschreven in een oude taal. Een meesterkunstenaar heeft de plaatjes gemaakt.",
  g = { {"duisters", "dark (duister)"}, {"doorzoek", "search through (doorzoeken)"}, {"bedoelingen", "intentions (bedoeling)"}, {"leren", "teach"}, {"aanwijzing", "clue"}, {"meesterkunstenaar", "master artist"}, {"plaatjes", "illustrations, pictures (plaatje)"} },
},

[950] = { en = "Return to Onu", tier = 1,
  t = "Terug naar Onu",
  d = "In de Twilight Tome kijken maakt je gek. Na maar één korte blik begint de tekst te zwemmen en te dansen. De ooit zo mooie versieringen draaien zich in afschuwelijke vormen.$B$BJe kunt nog net één bladzijde met krankzinnige krabbels eruit scheuren. Dan word je duizelig en val je bijna flauw.",
  o = "Breng Onu de Insane Scribbles die je hebt gevonden.",
  p = "$N. Je bent terug.",
  c = "Er hangt een chaotische oermagie rond dit stuk perkament vol krabbels. Ik voel er het werk van de oude wezens in.$b$bLaten we hopen dat het laat zien wat de Twilight's Hammer in Darkshore wil...",
  g = { {"blik", "glance, look"}, {"ooit", "once, ever"}, {"versieringen", "decorations, scrollwork (versiering)"}, {"afschuwelijke", "grotesque, horrible (afschuwelijk)"}, {"krankzinnige", "insane (krankzinnig)"}, {"krabbels", "scribbles (krabbel)"}, {"scheuren", "tear"}, {"duizelig", "dizzy"}, {"flauw vallen", "to faint (flauwvallen)"}, {"chaotische", "chaotic (chaotisch)"}, {"oermagie", "primal magic"}, {"perkament", "parchment"}, {"wezens", "beings (wezen)"} },
},

[982] = { en = "Deep Ocean, Vast Sea", tier = 1,
  t = "Diepe oceaan, wijde zee",
  d = "Voor de kust van Darkshore, ten noorden van ons, liggen twee scheepswrakken: de Silver Dawning en de Mist Veil. Een tijd geleden kregen beide schepen problemen met die vervloekte murlocs, toen ze over de wijde zee naar Auberdine voeren. Nu liggen ze op de bodem van de oceaan, als trofeeën voor die monsters.$B$BGeen van beide kapiteins heeft die nacht overleefd. Hun logboeken en andere spullen liggen nog beneden, in kistjes met een slot. Ik wil graag dat je ze voor ons terughaalt. Het zou veel betekenen voor de bemanningsleden die hier nog in de buurt zijn.",
  o = "Haal de Silver Dawning's Lockbox en de Mist Veil's Lockbox terug voor Gorbold Steelhand in Auberdine. Je vindt ze allebei in de wrakken van de schepen ten noorden van het dorp.",
  p = "De kapiteins van die schepen waren goede nachtelfen. Ze verdienen een beter lot dan ze hebben gekregen. Misschien kunnen hun geesten het best rust vinden als we voor hun persoonlijke spullen zorgen.",
  c = "Je hebt ons hier in Auberdine een grote dienst bewezen, jongen. We zorgen ervoor dat hun spullen goed worden behandeld.$b$bEn jij: neem dit alsjeblieft. Het is het minste wat ik kan doen voor iemand die zo dapper is om dingen recht te zetten.",
  g = { {"wijde", "vast, wide (wijd)"}, {"scheepswrakken", "shipwrecks (scheepswrak)"}, {"vervloekte", "blasted, cursed (vervloekt)"}, {"voeren", "sailed (varen)"}, {"bodem", "bottom"}, {"trofeeën", "trophies (trofee)"}, {"overleefd", "survived (overleven)"}, {"logboeken", "logs, logbooks (logboek)"}, {"kistjes", "small chests, lockboxes (kist)"}, {"bemanningsleden", "crew members (bemanningslid)"}, {"lot", "fate"}, {"persoonlijke", "personal (persoonlijk)"}, {"behandeld", "handled, taken care of (behandelen)"}, {"recht te zetten", "to set right (rechtzetten)"} },
},

[1138] = { en = "Fruit of the Sea", tier = 1,
  t = "Vruchten van de zee",
  d = "Ik hou van krab. Krabben zijn de vruchten van de zee! Je kunt krab in de oven bakken, barbecueën, koken en grillen. Je kunt ze in de pan bakken, frituren en roerbakken. Er is krabsalade, krabsoep, krabstoofpot, peperkrab, citroenkrab, whipper-root-krab en Ironforge-verrassingskrab. Dat is... dat is het wel zo'n beetje.$B$BIk ben nu hier aan het vissen, dus ik kan geen Fine Crab Chunks halen. Je kunt ze uit Reef Crawlers en Encrusted Tide Crawlers halen. Je kunt er veel mee maken. Je kunt krab in de oven bakken, barbecueën, koken...",
  o = "Verzamel 6 Fine Crab Chunks voor Gubber Blump in Auberdine.",
  p = "...citroenkrab, whipper-root-krab en Ironforge-verrassingskrab. Dat is het wel zo'n beetje.$B$BO, hallo $N. Heb je die Fine Crab Chunks waar ik het over had?",
  c = "Wauw, deze Fine Crab Chunks zijn precies wat ik nodig heb. Bedankt, $N! Ik heb dit een tijdje geleden gevonden toen ik aan het vissen was, en ik heb er niks aan. Misschien kun jij er iets mee doen. Je kunt er in elk geval geen goede krabgerechten mee maken.$B$BIk heb je alles over krabben verteld, toch?",
  g = { {"vruchten", "fruits (vrucht)"}, {"krab", "crab"}, {"koken", "boil, cook"}, {"frituren", "deep fry"}, {"roerbakken", "stir fry"}, {"krabstoofpot", "crab stew"}, {"verrassingskrab", "surprise crab"}, {"zo'n beetje", "about, more or less"}, {"vissen", "fishing, to fish"}, {"ik heb er niks aan", "I have no use for it"}, {"krabgerechten", "crab dishes (gerecht)"} },
},

[945] = { en = "Therylune's Escape", tier = 1,
  t = "De ontsnapping van Therylune",
  d = "Help!$B$BIk liep rond bij de Master's Glaive, en toen gingen die vieze cultisten om me heen staan. Gelukkig ben ik goed in verstoppen!!$B$BKun je me hier weg helpen? En ik moet mijn zus Therysil laten weten dat het goed met me gaat. Ze is in Ashenvale, in het zuiden, bij de Shrine of Aessina.",
  o = "Help Therylune ontsnappen en vertel Therysil bij de Shrine of Aessina dat haar zus veilig is.",
  c = "Waar was mijn zus?? Therylune vindt het niet erg om vies te worden, maar toch! Dat is wel heel ver om rond te dwalen, en de Master's Glaive is een ongezonde plek...$B$BNou, dank je wel, $N. Wat aardig van je dat je me laat weten dat het goed met haar gaat.",
  e = "Begeleid Therylune weg van de Master's Glaive",
  g = { {"ontsnapping", "escape"}, {"cultisten", "cultists (cultist)"}, {"om me heen", "around me"}, {"verstoppen", "hiding"}, {"laten weten", "let know"}, {"ontsnappen", "escape"}, {"toch", "still, all the same"}, {"rond te dwalen", "to wander around (rondwalen)"}, {"ongezonde", "unwholesome, unhealthy (ongezond)"}, {"begeleid", "escort (begeleiden)"} },
},

[965] = { en = "The Tower of Althalaxx", tier = 1,
  t = "De Tower of Althalaxx",
  d = "Gegroet, jonge $r. Ik ben Elissa Starbreeze, en het is mijn taak om Auberdine tegen gevaar te beschermen.$b$bDaarom heb ik Balthule Shadowstrike gestuurd om de vreemde dingen te bekijken die gebeuren rond de Tower of Althalaxx, in het noordoosten.$b$bHij had al lang terug moeten zijn. Ik ben bang dat hij in het bos een onverwacht gevaar is tegengekomen. Ik zou het heel fijn vinden als je hem zoekt en kijkt of het goed met hem gaat.",
  o = "Zoek Balthule Shadowstrike bij de Tower of Althalaxx in Darkshore.",
  c = "Heeft Elissa je gestuurd? Dan breng je goed nieuws. Ik heb zorgwekkend nieuws voor haar, maar ik had geen manier om het bij haar te krijgen.",
  g = { {"gegroet", "hail, greetings"}, {"beschermen", "protect"}, {"daarom", "for that reason"}, {"bekijken", "observe, look at"}, {"had terug moeten zijn", "should have returned"}, {"onverwacht", "unforeseen, unexpected"}, {"tegengekomen", "encountered (tegenkomen)"}, {"zorgwekkend", "troubling"} },
},

[966] = { en = "The Tower of Althalaxx", tier = 1,
  t = "De Tower of Althalaxx",
  d = "Een groep heksenmeesters heeft zich in en rond de toren gevestigd. Ik was eerder teruggegaan naar Auberdine om het aan Elissa te melden. Maar ik was bang dat ik iets zou missen als ik weg was.$b$bDelgren vermoedde al dat zo'n groep zich bij de toren zou verzamelen, maar hij wist niet waarom.$b$bIk heb een paar stukjes perkament te pakken gekregen die de heksenmeesters bij zich dragen. Maar ik heb er meer nodig om de puzzel af te maken. Ik waarschuw je wel: ga de toren niet in. De heksenmeesters daarbinnen zijn veel machtiger!",
  o = "Verzamel 4 Worn Parchments voor Balthule Shadowstrike bij de Tower of Althalaxx.",
  p = "Heb je nog meer van hun perkamenten gevonden? Als je ze vindt, kan ik een groter beeld van de sekte in elkaar zetten.",
  c = "Heel erg bedankt, $n. Dit zou wat licht moeten werpen op deze bijeenkomst van heksenmeesters...$b$bHm... de Cult of the Dark Strand... Van deze groep heb ik nog nooit gehoord. Omdat ik niets over hun geschiedenis weet, is het bijna onmogelijk om te zeggen wat hun plannen zijn.$b$bWe kunnen niet langer wachten. Delgren moet meteen gewaarschuwd worden.",
  g = { {"heksenmeesters", "warlocks (heksenmeester)"}, {"gevestigd", "settled, taken up residence (zich vestigen)"}, {"melden", "report"}, {"vermoedde", "suspected (vermoeden)"}, {"perkament", "parchment"}, {"te pakken gekregen", "got hold of (te pakken krijgen)"}, {"waarschuw", "warn (waarschuwen)"}, {"machtiger", "more powerful (machtig)"}, {"in elkaar zetten", "piece together"}, {"licht werpen op", "shed light on"}, {"bijeenkomst", "gathering"}, {"onmogelijk", "impossible"}, {"gewaarschuwd", "warned (waarschuwen)"} },
},

[967] = { en = "The Tower of Althalaxx", tier = 1,
  t = "De Tower of Althalaxx",
  d = "Mijn meester, Delgren the Purifier, is een paladijn. Hij helpt ons vriendelijk om onze bossen te verdedigen tegen de demonen en de ondoden. Hij heeft me veel geleerd over het Heilige Licht en over de kunst van het vechten.$b$bDelgren moet meteen horen wat de sekte doet.$b$bJe vindt hem ver ten zuiden van hier, in Maestra's Post in Ashenvale Forest. Wees snel. Ik ben bang dat het gevaar van de Dark Strand elk uur groter wordt.",
  o = "Breng de brief van Balthule naar Delgren the Purifier in Ashenvale Forest.",
  p = "Heb je iets met mij te bespreken, $C?",
  c = "Als je het niet erg vindt dat ik het zeg: je lijkt nogal goed uitgerust voor een boodschapper, hm? Balthule wilde zeker weten dat zijn brief in mijn handen kwam, denk ik. Eens kijken wat hij te zeggen heeft...$B$BDit is verontrustend nieuws. Als er ondoden of demonische krachten worden gevonden, help ik de Sentinels om ze te vernietigen.$B$BEerst was ik niet gewend aan de manieren van de nachtelfen. Maar nu heb ik veel respect voor hen als bondgenoten.",
  g = { {"paladijn", "paladin"}, {"verdedigen", "defend"}, {"ondoden", "undead (ondode)"}, {"Heilige Licht", "Holy Light"}, {"sekte", "cult"}, {"bespreken", "discuss"}, {"uitgerust", "equipped (uitrusten)"}, {"boodschapper", "messenger"}, {"eens kijken", "let's see"}, {"verontrustend", "disturbing"}, {"demonische", "demonic (demonisch)"}, {"gewend aan", "accustomed to"}, {"manieren", "manners, ways (manier)"}, {"bondgenoten", "allies (bondgenoot)"} },
},

[2139] = { en = "Tharnariun's Hope", tier = 1,
  t = "De hoop van Tharnariun",
  d = "Het overleven van ons volk en ons land heeft een trieste prijs, $N.$B$BJe hebt het bloed van de dienaren van de natuur vergoten. Je hebt veel zieke dieren gedood. De mensen van Auberdine zijn je veel verschuldigd, want de pijn van het bos is minder geworden, al is het maar voor even.$B$BIk heb nog één laatste taak voor je. Maar let op: je zult weer moeten doden. Ik hoop dat dit de laatste keer is dat ik je om hulp vraag, $N.$B$BIn een grot in het noordoosten, bij Bashal'Aran, woont de Den Mother. Dood haar.",
  o = "Zoek de Den Mother en dood haar.",
  p = "Nu de besmette Den Mother dood is, komen er minder Rabid Thistle Bears ons land binnen. Verlies geen tijd, $N.",
  c = "Je hebt met moed en eer voor Auberdine gevochten, $N. In ons land, verscheurd door oorlog, zijn dood en wanhoop heel gewoon. Velen zullen de uitdaging van het leven in ons nieuwe thuis niet aangaan. Ze verstoppen zich liever in hun huizen, of ze vluchten naar de beter verdedigde landen van de Alliance.$b$bDank je, $N. Misschien vechten we binnenkort zij aan zij, als kameraden tegen een andere vijand.",
  g = { {"overleven", "survival, to survive"}, {"trieste", "unfortunate, sad (triest)"}, {"dienaren", "servants (dienaar)"}, {"vergoten", "spilled (vergieten)"}, {"verschuldigd", "indebted, owed"}, {"al is het maar voor even", "even if only for a moment"}, {"besmette", "infected (besmet)"}, {"eer", "honor"}, {"verscheurd", "torn (verscheuren)"}, {"wanhoop", "despair"}, {"uitdaging", "challenge"}, {"aangaan", "take on, rise to"}, {"verdedigde", "fortified, defended (verdedigd)"}, {"zij aan zij", "side by side"}, {"kameraden", "comrades (kameraad)"} },
},

[4740] = { en = "WANTED: Murkdeep!", tier = 1,
  t = "GEZOCHT: Murkdeep!",
  d = "Let op!$B$BEr is een beloning voor de dood van de murloc \"Murkdeep\". Dit gemene beest is verantwoordelijk voor de dood van minstens één Sentinel. Men denkt ook dat hij minstens twee vrachtschepen heeft laten zinken in het water voor Darkshore!$B$BMurkdeep is het laatst gezien bij een murlockamp met hutten ten zuiden van Auberdine. Men denkt dat hij de hutten daar beschermt. Wie de beloning wil ophalen, moet zich melden bij Sentinel Glynda Nal'Shea in Auberdine.$B$BDe dorpsraad van Auberdine",
  o = "Zoek de murloc die Murkdeep heet en dood hem. Men denkt dat het beest de murlochutten ten zuiden van Auberdine verdedigt, langs het water.$B$BMeld de dood van Murkdeep aan Sentinel Glynda Nal'Shea in Auberdine.",
  p = "Gegroet, $c. Waarmee kunnen de Sentinels je vandaag helpen? Misschien kom je vragen naar de beloning voor Murkdeep?",
  c = "Nou, zo te zien kom je niet alleen maar vragen! De burgers zullen blij zijn als ze horen dat ze vannacht wat rustiger en veiliger kunnen slapen.$b$bVandaag ben jij voor de mensen van Auberdine de uitvoerder van het recht geweest, $N. Daarom wil ik je dit geven als passende beloning... voor een echte held van het volk van Auberdine.",
  g = { {"gezocht", "wanted (zoeken)"}, {"beloning", "reward, bounty"}, {"verantwoordelijk", "responsible"}, {"minstens", "at least"}, {"men denkt", "it is thought"}, {"vrachtschepen", "cargo vessels (vrachtschip)"}, {"zinken", "sink"}, {"hutten", "huts (hut)"}, {"ophalen", "claim, collect"}, {"dorpsraad", "village council"}, {"burgers", "citizens (burger)"}, {"uitvoerder", "executioner, one who carries out"}, {"het recht", "justice"}, {"passende", "suitable, fitting (passend)"} },
},

[4763] = { en = "The Blackwood Corrupted", tier = 1,
  t = "De verdorven Blackwood",
  d = "We weten nu dat de verdorvenheid van de furbolgs voor een deel van de saters komt. Ze hebben macht over hen via talismannen, waar ze magie doorheen sturen. Als de furbolgs nog een kans op redding hebben, moeten we de sater-verderver naar buiten lokken en die talisman pakken!$B$BVul deze schaal bij onze maanbron en neem monsters van het voedsel van de furbolgs uit hun kamp in het noorden. Meng ze en zet de schaal bij het kampvuur aan de rivier. Elke furbolg die ervan eet, wordt net lang genoeg gereinigd om de sater-verderver naar buiten te lokken... En die moet jij dan doden!",
  o = "Vul de Empty Cleansing Bowl bij de Auberdine Moonwell.$B$BVerzamel een monster van fruit, noten en graan uit de noordelijke kampen van de Blackwood-furbolgs.$B$BMeng de schaal en zet hem bij het kampvuur dat het dichtst bij de Cliffspring River ligt, in het noordelijke kamp. Zo roep je de sater-verderver op.$B$BPak de Talisman of Corruption en breng hem naar Thundris Windweaver in Auberdine.",
  p = "De Talisman of Corruption is een duister voorwerp dat alleen dient om het evenwicht van de natuur te verstoren. Haal dit voorwerp bij de sater die de furbolgs kwelt, wie dat ook is. Breng het dan naar mij, zodat ik het kan vernietigen. Dan hebben we vandaag een grote overwinning behaald!",
  c = "We zijn nog maar net begonnen aan deze oorlog om ons bos terug te winnen van de krachten van verdorvenheid. Maar vandaag is er een gevecht gewonnen! $N, de mensen van Auberdine zijn je veel dank verschuldigd. Die schuld kunnen we nooit makkelijk terugbetalen. Neem dit alsjeblieft aan, samen met onze dank. Wat we hier vandaag hebben geleerd, kan onze furbolgvrienden misschien ooit voorgoed bevrijden uit de ketenen van kwelling.",
  g = { {"verdorvenheid", "corruption"}, {"saters", "satyrs (sater)"}, {"talismannen", "talismans (talisman)"}, {"redding", "salvation, rescue"}, {"sater-verderver", "satyr corruptor"}, {"lokken", "lure"}, {"maanbron", "moonwell"}, {"gereinigd", "cleansed (reinigen)"}, {"verstoren", "disturb, pervert"}, {"kwelt", "torments (kwellen)"}, {"overwinning", "victory"}, {"terug te winnen", "to reclaim (terugwinnen)"}, {"verschuldigd", "owed"}, {"ketenen", "shackles, chains (keten)"}, {"kwelling", "torment"} },
},

})

